class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long pow(long b, long e) {
    long r = 1;
    for (b %= MOD; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % MOD;
      b = b * b % MOD;
    }
    return r;
  }

  public int magicalSum(int m, int k, int[] nums) {
    long[] fact = new long[m + 1], inv = new long[m + 1];
    fact[0] = 1;
    for (int i = 1; i <= m; i++) fact[i] = fact[i - 1] * i % MOD;
    for (int i = 0; i <= m; i++) inv[i] = pow(fact[i], MOD - 2);
    long[][][] dp = new long[m + 1][m + 1][k + 1];
    dp[0][0][0] = 1;
    for (int num : nums) {
      long[] w = new long[m + 1];
      long p = 1;
      for (int c = 0; c <= m; c++) {
        w[c] = p * inv[c] % MOD;
        p = p * num % MOD;
      }
      long[][][] nd = new long[m + 1][m + 1][k + 1];
      for (int used = 0; used <= m; used++) {
        for (int carry = 0; carry <= m; carry++) {
          for (int ones = 0; ones <= k; ones++) {
            long v = dp[used][carry][ones];
            if (v == 0) continue;
            for (int c = 0; used + c <= m; c++) {
              int total = carry + c, no = ones + (total & 1);
              if (no > k) continue;
              int nc = total >> 1;
              nd[used + c][nc][no] = (nd[used + c][nc][no] + v * w[c]) % MOD;
            }
          }
        }
      }
      dp = nd;
    }
    long ans = 0;
    for (int carry = 0; carry <= m; carry++) {
      int extra = Integer.bitCount(carry);
      if (k - extra >= 0) ans = (ans + dp[m][carry][k - extra]) % MOD;
    }
    return (int) (ans * fact[m] % MOD);
  }
}
